import {signupInput,loginInput} from '@crew/shared';
export function authDestination(value) {
  if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||/[\u0000-\u0020\\]/.test(value))return '/';
  const path=value.split('?')[0];
  if(['/login','/signup','/reset','/invitations/accept'].some(item=>path===item||path.startsWith(item+'/')))return '/';
  return value;
}
export function authInput(values,signup=false) {
  const body=signup?signupInput(values):loginInput(values);
  if(signup&&values.confirmation!==values.password){
    const error=new Error('Passwords do not match');error.details={confirmation:'Enter the same password again'};throw error;
  }
  return body;
}
export function createAuthAttempt({send,onSuccess,notify=()=>{}}) {
  let generation=0,active=null,disposed=false;
  let state={busy:false,error:null};
  const update=patch=>{state={...state,...patch};if(!disposed)notify(state);};
  return {
    get:()=>({...state}),
    fail(error){if(!state.busy&&!disposed)update({error});},
    clearError(){if(state.error&&!disposed)update({error:null});},
    async run(body){
      if(disposed||active)return false;
      const owner={generation:++generation,controller:new AbortController()};active=owner;update({busy:true,error:null});
      try{
        const result=await send(body,{signal:owner.controller.signal});
        if(disposed||active!==owner||owner.generation!==generation)return false;
        await onSuccess(result);return true;
      }catch(error){
        if(!disposed&&active===owner&&owner.generation===generation)update({error});
        return false;
      }finally{
        if(active===owner){active=null;update({busy:false});}
      }
    },
    dispose(){disposed=true;generation++;const owner=active;active=null;owner?.controller.abort();}
  };
}

