export function parseLocation(hash='') {
  const value=hash.replace(/^#/,'')||'/';
  const separator=value.indexOf('?');
  const pathname=separator<0?value:value.slice(0,separator),search=separator<0?'':value.slice(separator+1);
  return {pathname,query:Object.fromEntries(new URLSearchParams(search))};
}
export function matchRoute(pattern,pathname) {
  const expected=pattern.split('/').filter(Boolean);
  const actual=pathname.split('/').filter(Boolean);
  if(expected.length!==actual.length)return null;
  const params={};
  for(let i=0;i<expected.length;i++){
    if(expected[i].startsWith(':')){
      try{params[expected[i].slice(1)]=decodeURIComponent(actual[i]);}catch{return null;}
    }else if(expected[i]!==actual[i])return null;
  }
  return params;
}
export function navigate(path) {window.location.hash=path;}
export function routeLink(path,query={}) {
  const search=new URLSearchParams(Object.entries(query).filter(([,v])=>v!==undefined&&v!==''));
  return '#'+path+(search.size?'?'+search:'');
}

