test('actual pinned browser authenticates deep links protects abandoned forms and recovers a failed session check',{timeout:35000},async()=>{
  const server=await testServer();let child;
  try{
    const request=server.agent();await request('POST','/auth/signup',{name:'Shell Owner',email:'shell-owner@example.test',password:'correct shell password'});
