    const settings={url:server.url,issueId:issue.id,orgId:org.id,projectId:project.id};
    const result=await new Promise((resolve,reject)=>{
      child=spawn('/usr/bin/python3',[fileURLToPath(new URL('./shell-browser.py',import.meta.url)),JSON.stringify(settings)],{detached:true});
      let stdout='',stderr='';const timer=setTimeout(()=>{try{process.kill(-child.pid,'SIGKILL');}catch{}reject(new Error('Shell browser exceeded bounded deadline'));},30000);
      child.stdout.on('data',data=>stdout+=data);child.stderr.on('data',data=>stderr+=data);
