test('authentication admits one current submission before the first render can disable the button',async()=>{
  let release,calls=0;const success=[];
  const attempt=createAuthAttempt({send:()=>{calls++;return new Promise(resolve=>release=resolve);},onSuccess:value=>success.push(value)});
  const first=attempt.run({email:'one'});assert.equal(await attempt.run({email:'two'}),false);assert.equal(calls,1);
  release({user:{id:'one'}});assert.equal(await first,true);assert.equal(success.length,1);assert.equal(attempt.get().busy,false);
});
test('disposing an abandoned auth form aborts its request and suppresses late account replacement',async()=>{
  let release,signal;const success=[],states=[];
  const attempt=createAuthAttempt({send:(body,options)=>{signal=options.signal;return new Promise(resolve=>release=resolve);},onSuccess:value=>success.push(value),notify:value=>states.push(value)});
  const result=attempt.run({});const before=states.length;attempt.dispose();assert(signal.aborted);release({user:{id:'late'}});
  assert.equal(await result,false);assert.deepEqual(success,[]);assert.equal(states.length,before);assert.equal(await attempt.run({}),false);
});
test('auth errors preserve ownership and require a deliberate new attempt',async()=>{
  let calls=0;const failure=new Error('Denied');
  const attempt=createAuthAttempt({send:async()=>{calls++;if(calls===1)throw failure;return {user:{id:'ok'}};},onSuccess:()=>{}});
  assert.equal(await attempt.run({}),false);assert.equal(calls,1);assert.equal(attempt.get().error,failure);
  attempt.clearError();assert.equal(attempt.get().error,null);assert.equal(await attempt.run({}),true);assert.equal(calls,2);
});
test('local form validation failure never sends a request and cannot replace a busy attempt',async()=>{
